gvJ(){return"\ub358\uc804\uacfc \ub808\uc774\ub4dc"},
gvI(){return"\ubaa8\ud5d8 \ud0ed\uc758 \ub358\uc804. \ub358\uc804\uc740 \ud63c\uc790 \ud569\ub2c8\ub2e4. \ub808\uc774\ub4dc\ub294 2~5\uc778 \ud30c\ud2f0\uac00 \ud544\uc694\ud558\uba70 \ud30c\ud2f0 \ucc3e\uae30\ub85c \ub9e4\uce6d\ub429\ub2c8\ub2e4. \ub808\uc774\ub4dc \ubcf4\uc2a4\ub294 \uc138\ud2b8 \uc544\uc774\ud15c\uacfc \ud3ab \uc54c\uc744 \ub5a8\uc5b4\ub728\ub9bd\ub2c8\ub2e4."},
