gvL(){return"\uc774\ubca4\ud2b8"},
gvK(){return"\ubaa8\ud5d8 \ud0ed\uc758 \uc774\ubca4\ud2b8. \uc6d4\ub4dc \ubcf4\uc2a4\uc640 \uce68\uacf5\uc5d0 \ucc38\uac00\ud558\uace0 \ub9e4\uc77c \uc2dc\uc98c \ud1a0\ud070\uc744 \ubc1b\uc73c\uc138\uc694. \uce74\ub4dc\ub97c \ub204\ub974\uba74 \ubc29\ubc95\uacfc \ubcf4\uc0c1\uc774 \ub098\uc635\ub2c8\ub2e4."},
