ML(a){return"\u0412\u044b\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044f \u0438\u0437 \u0448\u0430\u043d\u0441\u0430 \u043f\u043e\u043f\u0430\u0434\u0430\u043d\u0438\u044f \u0432\u0440\u0430\u0433\u0430. \u041d\u0435 \u0431\u043e\u043b\u0435\u0435 "+a+"%."},
MG(a){return"\u0428\u0430\u043d\u0441 \u0443\u043c\u0435\u043d\u044c\u0448\u0438\u0442\u044c \u0432\u0445\u043e\u0434\u044f\u0449\u0438\u0439 \u0443\u0434\u0430\u0440 \u0432\u0434\u0432\u043e\u0435. \u041d\u0435 \u0431\u043e\u043b\u0435\u0435 "+a+"%."},
MK(a){return"\u041a\u0430\u0436\u0434\u044b\u0439 \u043f\u043e\u043b\u0443\u0447\u0435\u043d\u043d\u044b\u0439 \u0443\u0434\u0430\u0440 \u0441\u043d\u0438\u0436\u0430\u0435\u0442\u0441\u044f \u043d\u0430 \u044d\u0442\u0443 \u0434\u043e\u043b\u044e. \u041d\u0435 \u0431\u043e\u043b\u0435\u0435 "+a+"%."},
gMO(){return"\u0412\u044b \u0438\u0441\u0446\u0435\u043b\u044f\u0435\u0442\u0435\u0441\u044c \u043d\u0430 \u044d\u0442\u0443 \u0434\u043e\u043b\u044e \u043d\u0430\u043d\u0435\u0441\u0451\u043d\u043d\u043e\u0433\u043e \u0443\u0440\u043e\u043d\u0430."},
MM(a){return"\u0414\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u0443\u0440\u043e\u043d \u043f\u043e \u0432\u0440\u0430\u0433\u0430\u043c \u0441 "+a+"% \u041e\u0417 \u0438 \u043d\u0438\u0436\u0435."},
gMP(){return"\u0414\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u0443\u0440\u043e\u043d \u0434\u043e \u044d\u0442\u043e\u0439 \u0432\u0435\u043b\u0438\u0447\u0438\u043d\u044b \u043f\u043e \u043c\u0435\u0440\u0435 \u043f\u0430\u0434\u0435\u043d\u0438\u044f \u0432\u0430\u0448\u0438\u0445 \u041e\u0417."},
gMQ(){return"\u0410\u043a\u0442\u0438\u0432\u043d\u044b\u0439 \u043f\u0438\u0442\u043e\u043c\u0435\u0446 \u0434\u043e\u0431\u0430\u0432\u043b\u044f\u0435\u0442 \u044d\u0442\u0443 \u0434\u043e\u043b\u044e \u043a \u043a\u0430\u0436\u0434\u043e\u043c\u0443 \u0432\u0430\u0448\u0435\u043c\u0443 \u0443\u0434\u0430\u0440\u0443."},
gGO(){return"\u041b\u0438\u0446\u043e"},
gGQ(){return"\u041f\u0440\u0438\u0447\u0451\u0441\u043a\u0430"},
