guL(){return"\u0421\u043f\u043e\u0441\u043e\u0431\u043d\u043e\u0441\u0442\u0438 \u0440\u0430\u0441\u044b"},
gJj(){return"\u0432\u0441\u0435 \u043f\u0430\u0441\u0441\u0438\u0432\u043d\u044b\u0435"},
