Js(a,b){return"+"+a+"% \u0431\u043e\u043d\u0443\u0441\u043d\u043e\u0433\u043e \u043e\u043f\u044b\u0442\u0430: "+b},
gpY(){return"\u042f\u0437\u044b\u043a"},
gqw(){return"\u041f\u043e\u0436\u0430\u043b\u043e\u0432\u0430\u0442\u044c\u0441\u044f"},
KS(a){return"\u041f\u043e\u0436\u0430\u043b\u043e\u0432\u0430\u0442\u044c\u0441\u044f \u043d\u0430 "+a},
