gKK(){return"\u0427\u0438\u0442\u044b \u0438\u043b\u0438 \u0431\u043e\u0442\u044b"},
gKM(){return"\u041e\u0441\u043a\u043e\u0440\u0431\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0435 \u0438\u043c\u044f"},
gKR(){return"\u0421\u043f\u0430\u043c \u0438\u043b\u0438 \u0440\u0435\u043a\u043b\u0430\u043c\u0430"},
gKP(){return"\u041c\u043e\u0448\u0435\u043d\u043d\u0438\u0447\u0435\u0441\u0442\u0432\u043e"},
gKO(){return"\u0414\u0440\u0443\u0433\u043e\u0435"},
gKN(){return"\u041f\u043e\u0434\u0440\u043e\u0431\u043d\u043e\u0441\u0442\u0438 (\u043d\u0435\u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u043e)"},
gKQ(){return"\u0416\u0430\u043b\u043e\u0431\u0430 \u043e\u0442\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0430. \u0421\u043f\u0430\u0441\u0438\u0431\u043e."},
gEi(){return"\u041d\u0435\u043b\u044c\u0437\u044f \u043f\u043e\u0436\u0430\u043b\u043e\u0432\u0430\u0442\u044c\u0441\u044f \u043d\u0430 \u0441\u0432\u043e\u0435\u0433\u043e \u043f\u0435\u0440\u0441\u043e\u043d\u0430\u0436\u0430."},
gHK(){return"\u0412\u0430\u0448\u0430 \u0436\u0430\u043b\u043e\u0431\u0430 \u0440\u0430\u0441\u0441\u043c\u043e\u0442\u0440\u0435\u043d\u0430"},
gom(){return"\u0421\u043f\u0440\u0430\u0432\u043e\u0447\u043d\u0438\u043a"},
gwa(){return"\u041f\u043e\u0438\u0441\u043a \u043f\u043e \u0441\u043f\u0440\u0430\u0432\u043e\u0447\u043d\u0438\u043a\u0443"},
gvW(){return"\u041d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u043d\u0430\u0439\u0434\u0435\u043d\u043e."},
gwb(){return"\u041f\u043e\u043a\u0430\u0437\u0430\u0442\u044c"},
gjz(){return"\u0414\u0430\u043b\u0435\u0435"},
gzz(){return"\u041d\u0430\u0437\u0430\u0434"},
gM4(){return"\u041f\u0440\u043e\u043f\u0443\u0441\u0442\u0438\u0442\u044c \u043e\u0431\u0443\u0447\u0435\u043d\u0438\u0435"},
gM5(){return"\u041d\u0430\u0447\u0430\u0442\u044c \u0438\u0433\u0440\u0443"},
