gvz(){return"\u0410\u043a\u043a\u0430\u0443\u043d\u0442, \u044f\u0437\u044b\u043a \u0438 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0430"},
gvy(){return"\u0421\u043f\u0438\u0441\u043e\u043a \u043f\u0435\u0440\u0441\u043e\u043d\u0430\u0436\u0435\u0439, \u0437\u043d\u0430\u0447\u043e\u043a \u0430\u043a\u043a\u0430\u0443\u043d\u0442\u0430 \u0432\u0432\u0435\u0440\u0445\u0443. \u0421\u043c\u0435\u043d\u0438\u0442\u0435 \u044f\u0437\u044b\u043a \u0438\u043b\u0438 \u043f\u0430\u0440\u043e\u043b\u044c, \u043d\u0430\u043f\u0438\u0448\u0438\u0442\u0435 \u0432 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0443, \u0441\u043a\u0430\u0447\u0430\u0439\u0442\u0435 \u0434\u0430\u043d\u043d\u044b\u0435 \u0438\u043b\u0438 \u0443\u0434\u0430\u043b\u0438\u0442\u0435 \u0430\u043a\u043a\u0430\u0443\u043d\u0442."},
gqn(){return"\u0420\u0435\u0439\u0442\u0438\u043d\u0433"},
gqr(){return"\u041e\u0447\u043a\u0438"},
