gqq(){return"\u041f\u0440\u043e\u0444\u0435\u0441\u0441\u0438\u0438"},
gK2(){return"\u041f\u0440\u043e\u0445\u043e\u0436\u0434\u0435\u043d\u0438\u044f"},
guO(){return"\u041f\u043e\u0434\u0437\u0435\u043c\u0435\u043b\u044c\u044f"},
guQ(){return"\u0420\u0435\u0439\u0434\u044b"},
gK1(){return"\u0412\u0441\u0435 \u043a\u043b\u0430\u0441\u0441\u044b"},
gK4(){return"\u0418\u0437 \u0447\u0435\u0433\u043e \u0441\u043a\u043b\u0430\u0434\u044b\u0432\u0430\u044e\u0442\u0441\u044f \u043e\u0447\u043a\u0438"},
gK5(){return"\u041a\u0430\u0436\u0434\u043e\u0435 \u043f\u043e\u0434\u0437\u0435\u043c\u0435\u043b\u044c\u0435 \u0438 \u0440\u0435\u0439\u0434 \u0437\u0430\u0441\u0447\u0438\u0442\u044b\u0432\u0430\u044e\u0442\u0441\u044f \u043e\u0434\u0438\u043d \u0440\u0430\u0437. \u041e\u0431\u043d\u043e\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u0440\u0430\u0437 \u0432 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u043c\u0438\u043d\u0443\u0442."},
gK3(){return"\u0422\u0430\u0431\u043b\u0438\u0446\u0430 \u0435\u0449\u0451 \u043f\u043e\u0434\u0441\u0447\u0438\u0442\u044b\u0432\u0430\u0435\u0442\u0441\u044f."},
gqM(){return"\u041a\u0430\u0437\u043d\u0430 \u0438 \u0431\u0430\u043d\u043a"},
gwx(){return"\u041a\u0430\u0437\u043d\u0430 \u0433\u0438\u043b\u044c\u0434\u0438\u0438"},
gwm(){return"\u0411\u0430\u043d\u043a \u0433\u0438\u043b\u044c\u0434\u0438\u0438"},
