wq(a,b){return"\u041f\u0440\u0435\u0434\u043c\u0435\u0442\u043e\u0432 \u0432\u0437\u044f\u0442\u043e \u0441\u0435\u0433\u043e\u0434\u043d\u044f: "+a+" \u0438\u0437 "+b},
gwv(){return"\u0412\u0430\u0448\u0435 \u0437\u0432\u0430\u043d\u0438\u0435 \u043f\u043e\u043a\u0430 \u043d\u0435 \u0434\u0430\u0451\u0442 \u0434\u043e\u0441\u0442\u0443\u043f\u0430 \u043a \u0431\u0430\u043d\u043a\u0443 \u0433\u0438\u043b\u044c\u0434\u0438\u0438."},
gwr(){return"\u041e\u043f\u0435\u0440\u0430\u0446\u0438\u0438"},
