gDq(){return"\u041f\u0435\u0440\u0435\u0434 \u0440\u043e\u0441\u043f\u0443\u0441\u043a\u043e\u043c \u043e\u043f\u0443\u0441\u0442\u043e\u0448\u0438\u0442\u0435 \u043a\u0430\u0437\u043d\u0443 \u0438 \u0431\u0430\u043d\u043a."},
gDo(){return"\u0413\u0438\u043b\u044c\u0434\u0438\u044f \u0440\u0430\u0441\u043f\u0443\u0441\u043a\u0430\u0435\u0442\u0441\u044f, \u0432\u043d\u043e\u0441\u0438\u0442\u044c \u043d\u0435\u043b\u044c\u0437\u044f."},
