gDF(){return"\u041f\u0440\u0438\u0432\u044f\u0437\u0430\u043d\u043d\u044b\u0439 \u043f\u0440\u0435\u0434\u043c\u0435\u0442 \u043e\u0441\u0442\u0430\u0451\u0442\u0441\u044f \u0443 \u043f\u0435\u0440\u0441\u043e\u043d\u0430\u0436\u0430."},
gDG(){return"\u0421\u043d\u0430\u0447\u0430\u043b\u0430 \u0441\u043d\u0438\u043c\u0438\u0442\u0435 \u043f\u0440\u0435\u0434\u043c\u0435\u0442."},
gt1(){return"\u0421\u0442\u0430\u0432\u043a\u0430"},
gzC(){return"\u0421\u0442\u0430\u0432\u043a\u0430 \u0441\u0434\u0435\u043b\u0430\u043d\u0430."},
