guc(){return"\u0410\u0443\u043a\u0446\u0438\u043e\u043d"},
zt(a){return"\u0421\u0442\u0430\u0432\u043e\u043a \u043d\u0435\u0442, \u0441\u0442\u0430\u0440\u0442 "+a},
zw(a,b){return"\u041b\u0443\u0447\u0448\u0430\u044f \u0441\u0442\u0430\u0432\u043a\u0430 "+a+" (\u0441\u0442\u0430\u0432\u043e\u043a: "+b+")"},
gzx(){return"\u0432\u044b \u043b\u0438\u0434\u0438\u0440\u0443\u0435\u0442\u0435"},
